KG42.register("nodes-a3ee2c1212e8fc9f76558c8c",{"id":"COMP-2b436bb00a01fea8","code":"CLR010","label":"Individual rationality through nonnegative buyer utility","definition":"The utility obtained by a buyer participating in the Discriminatory k-DA must not be negative, which constitutes the individual rationality property of the trading outcome.","layer":"L5","template_code":"DA","concept_id":"participation.consumer","concept_ids":["participation.consumer"],"identity_dimensions":{"identity_fields":["Object: the utility of the buyer after participating in the transaction","Relationship: utility is non-negative","Output: buyer individual rationality guarantee"]},"exclusions":["This unit projects the buyer side","The source provides only a property definition, not a utility calculation formula"],"members":[{"id":"05-double_auction::v141-c-R007::V::participation.consumer","rule_id":"v141-c-R007","market_meaning":"Buyers must not incur negative utilities from participating in discriminatory k-DA. Scope: Buyer participation in discriminatory k-DA.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Buyer participation in discriminatory k-DA.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-09"]},"constraint_refs":["05-double_auction::v141-c-R007::v141-c-R007-C001"],"decision_anchor":"participation.consumer","source_rule_sha256":"536b7aeb1de052795e17b79c14b50d2a01fd0173ef5259e80b46b7f5397f7837","paper":"05-double_auction","rule_ref":"05-double_auction::v141-c-R007","node_id":"participation.consumer","function":"participation.consumer","unit_id":"05-double_auction::v141-a-M01::participation.consumer","mechanism_id":"v141-a-M01","anchor":true}],"paper_ids":["05-double_auction"],"evidence":[{"evidence_id":"v141-b-g01-ev-09","location":{"location_id":"src-22913ad574-p03-c1r3__v141-a-M01-validation","page":3,"printed_page":null,"section":"2.1","anchor_text":"g p all individual utilities for social welfare such that no participants are precluded from trading","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"An ideal auction mechanism encompasses four distinct properties: individual rationality (IR), budget balance (BB), incentive compatibility (IC), and economic efficiency (EE) [47]. An IR mechanism implies that no buyers/sellers shall result in negative utilities from participating in the auction. All four reviewed mechanisms exhibit IR. A BB mechanism does not financially subsidize or gain from transactions between buyers and sellers. Both VCG and TR are not BB as their market operators financially subsidize and gain from trades, respectively. IC motivates participants to bid their valuations truthfully. Both Discriminatory and Uniform k-DA do not have mechanisms to motivate truthful bidding as VCG and TR do. EE attempts to maximize the sum of all individual utilities for social welfare such that no participants are precluded from trading. Since buyer $\\gamma$ and seller $\\gamma$ are precluded from trading in TR, the mechanism, by default, does not maximize economic efficiency. While an ideal auction mechanism shall exhibit all four properties, it is important to note that the Myerson-Satterthwaite theorem [48] proves that no realistic mechanism can exhibit these four properties simultaneously.","paper":"05-double_auction","rule_id":"v141-c-R007","quote":"An ideal auction mechanism encompasses four distinct properties: individual rationality (IR), budget balance (BB), incentive compatibility (IC), and economic efficiency (EE) [47]. An IR mechanism implies that no buyers/sellers shall result in negative utilities from participating in the auction. All four reviewed mechanisms exhibit IR. A BB mechanism does not financially subsidize or gain from transactions between buyers and sellers. Both VCG and TR are not BB as their market operators financially subsidize and gain from trades, respectively. IC motivates participants to bid their valuations truthfully. Both Discriminatory and Uniform k-DA do not have mechanisms to motivate truthful bidding as VCG and TR do. EE attempts to maximize the sum of all individual utilities for social welfare such that no participants are precluded from trading. Since buyer $\\gamma$ and seller $\\gamma$ are precluded from trading in TR, the mechanism, by default, does not maximize economic efficiency. While an ideal auction mechanism shall exhibit all four properties, it is important to note that the Myerson-Satterthwaite theorem [48] proves that no realistic mechanism can exhibit these four properties simultaneously."}],"candidate_only":true,"classification_subtypes":["individual_rationality_property"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L5-155896d873","secondary_families":[],"stage":"L5","ontological_kind":"individual_rationality_property"},"semantic_definition":{},"source_units":[{"unit_id":"05-double_auction::v141-a-M01::participation.consumer","paper_id":"05-double_auction","mechanism_id":"v141-a-M01","function":"participation.consumer","source_occurrences":[{"id":"05-double_auction::v141-c-R007::V::participation.consumer","rule_id":"v141-c-R007","market_meaning":"Buyers must not incur negative utilities from participating in discriminatory k-DA. Scope: Buyer participation in discriminatory k-DA.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Buyer participation in discriminatory k-DA.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-09"]},"constraint_refs":["05-double_auction::v141-c-R007::v141-c-R007-C001"],"decision_anchor":"participation.consumer","source_rule_sha256":"536b7aeb1de052795e17b79c14b50d2a01fd0173ef5259e80b46b7f5397f7837"}],"constraints":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"Buyers must not incur negative utilities from participating in discriminatory k-DA. Scope: Buyer participation in discriminatory k-DA.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.consumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev-09"],"ref":"05-double_auction::v141-c-R007::v141-c-R007-C001","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-ev-09","location":{"location_id":"src-22913ad574-p03-c1r3__v141-a-M01-validation","page":3,"printed_page":null,"section":"2.1","anchor_text":"g p all individual utilities for social welfare such that no participants are precluded from trading","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"An ideal auction mechanism encompasses four distinct properties: individual rationality (IR), budget balance (BB), incentive compatibility (IC), and economic efficiency (EE) [47]. An IR mechanism implies that no buyers/sellers shall result in negative utilities from participating in the auction. All four reviewed mechanisms exhibit IR. A BB mechanism does not financially subsidize or gain from transactions between buyers and sellers. Both VCG and TR are not BB as their market operators financially subsidize and gain from trades, respectively. IC motivates participants to bid their valuations truthfully. Both Discriminatory and Uniform k-DA do not have mechanisms to motivate truthful bidding as VCG and TR do. EE attempts to maximize the sum of all individual utilities for social welfare such that no participants are precluded from trading. Since buyer $\\gamma$ and seller $\\gamma$ are precluded from trading in TR, the mechanism, by default, does not maximize economic efficiency. While an ideal auction mechanism shall exhibit all four properties, it is important to note that the Myerson-Satterthwaite theorem [48] proves that no realistic mechanism can exhibit these four properties simultaneously."}]}],"variables":[],"parameters":[]}],"source_definitions":[{"unit_id":"05-double_auction::v141-a-M01::participation.consumer","stage":"L5","subtype":"individual_rationality_property","projection_status":"clear","target_definition":"The utility obtained by a buyer participating in the Discriminatory k-DA must not be negative, which constitutes the individual rationality property of the trading outcome.","form_kind":"conceptual","identity_fields":["Object: the utility of the buyer after participating in the transaction","Relationship: utility is non-negative","Output: buyer individual rationality guarantee"],"variation_fields":["This unit projects the buyer side","The source provides only a property definition, not a utility calculation formula"],"constraint_refs":["05-double_auction::v141-c-R007::v141-c-R007-C001"],"paper_id":"05-double_auction","mechanism_id":"v141-a-M01","function":"participation.consumer","template_code":"DA"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/49"});
